from __future__ import absolute_import

from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass

logger = BackgroundLogger.Instance()


class Traces(BaseClass):
    """
    Accounts
    """

    def __init__(self):
        super(Traces, self).__init__()

    def get_traces_activation_status(self, **kwargs):
        timeout = kwargs.get("timeout", 30)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_traces_activation_status(timeout=timeout, connection=connection)

    def stop_uplane_trace_stream(self, **kwargs):
        trace_id = kwargs["trace_id"]
        timeout = kwargs.get("timeout", 30)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.stop_uplane_trace_stream(trace_id, timeout=timeout, connection=connection)

    def get_active_trace_streams(self, **kwargs):
        timeout = kwargs.get("timeout", 30)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_active_trace_streams(timeout=timeout, connection=connection)

    def start_uplane_trace_stream(self, **kwargs):
        trace_type = kwargs.get("trace_type", "Component")
        target_component = kwargs["target_component"]
        timeout = kwargs.get("timeout", 30)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.start_uplane_trace_stream(trace_type, target_component, timeout=timeout,
                                                             connection=connection)